// In the local development game, after tool startup:
// This facade is page-local; it is not a remote MCP server.
await window.mapleWebMCP.ready;
const tools = window.mapleWebMCP;
console.log(tools.mode); // Check native registration versus fallback.

const world = await tools.invoke('get_world_state', {});
const matches = await tools.invoke('find_objects', { query: 'train' });
// Read matches.content[0].text, then use a returned UUID:
// await tools.invoke('inspect_object', { query: returnedUuid });
const profile = await tools.invoke('get_runtime_profile', {});
const timing = await tools.invoke('measure_game_performance', {
  durationSeconds: 3,
});
// Each result has content; check isError before reading the payload.
// Timing is observed frame/CPU work, not a direct GPU measurement.
console.log({ world, matches, profile, timing });

